const projects = {
cat:{title:'校园猫 / Campus Cat',pages:[11,18],description:'把校园里的相遇，做成可以带走的陪伴。以真实校园流浪猫为原型，围绕毛绒本体、包装与角色卡构成系列商品。本人职责：选品、设计、采购。2026 年 6 月项目销量 3,000+（依据原作品集提供信息）；采购数量与销量分别记录。'},
elio:{title:'Elio / 角色与衍生',pages:[19,26],description:'从一个轮廓，到一整个世界。皇冠、表情与头身关系构成识别特征；头饰、道具与服装承载不同主题。北京 Oi 无限幻想，2025。参与 IP 产品设计、版权申请与工厂对接。工艺延展页面为设计交付提案，不代表历史量产参数。'},
gifts:{title:'校园纪念品 / Soft Memories',pages:[27,31],description:'被带走的，也是一段校园记忆。校园吉祥物与毕业纪念品，从甲方参考、面料寻找到样品确认。本人职责：设计、开发跟进、采购。手工练习单独标注，不作为官方合作项目。'},
animation:{title:'动画与叙事 / Moving Stories',pages:[5,10],description:'让画面，开始流动。《失忆者回忆录》：参与部分场景、中割及上色；《四无青年》：参与部分场景绘制与上色。动画及相关获奖、入围均为团队作品成果。',links:[['观看《失忆者回忆录》','https://www.bilibili.com/video/BV16u411n7Qu'],['观看《四无青年》','https://www.bilibili.com/video/BV1nz421878b']]},
visual:{title:'视觉档案 / Visual Archive',pages:[41,59],description:'从角色、场景到日常观察，收录视觉设计、同人创作、内容运营与手绘习作。同人作品并非官方授权合作；运营截图为原作品集记录时的状态。'},
concept:{title:'进行中的想象 / Work in Progress',pages:[32,40],description:'未解禁项目工作稿与概念计划，仅限约定范围查阅。项目状态以各页标注为准；计划性内容尚未执行。AI 辅助的概念讨论与能力练习不代表已完成商业交付。'}
};
const dialog=document.querySelector('#project-dialog');let activeKey='cat';let returnFocus;
function showProject(key){const project=projects[key];activeKey=key;document.querySelector('#dialog-title').textContent=project.title;document.querySelector('#dialog-description').textContent=project.description;document.querySelector('#dialog-label').textContent=`PROJECT ${String(Object.keys(projects).indexOf(key)+1).padStart(2,'0')} / 06`;const pages=document.querySelector('#project-pages');pages.replaceChildren();for(let n=project.pages[0];n<=project.pages[1];n++){const figure=document.createElement('figure');const img=document.createElement('img');img.src=`assets/page-${String(n).padStart(2,'0')}.jpg`;img.alt=`${project.title}，作品集第 ${n} 页`;img.width=1800;img.height=1200;img.loading=n===project.pages[0]?'eager':'lazy';const caption=document.createElement('figcaption');caption.textContent=`${project.title} / ${String(n).padStart(2,'0')} — 60`;figure.append(img,caption);pages.append(figure);}const links=document.querySelector('#project-links');links.replaceChildren();for(const [label,url] of project.links||[]){const a=document.createElement('a');a.textContent=label;a.href=url;a.target='_blank';a.rel='noopener noreferrer';links.append(a);}if(!dialog.open){returnFocus=document.activeElement;dialog.showModal();document.body.classList.add('modal-open');}dialog.scrollTop=0;document.querySelector('#close-dialog').focus();}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>showProject(button.dataset.project)));
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');returnFocus?.focus();});dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});document.querySelector('#next-project').addEventListener('click',()=>{const keys=Object.keys(projects);showProject(keys[(keys.indexOf(activeKey)+1)%keys.length]);});
